scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var hits = new global.EcsSecurity(new global.EcsAst(engine.rootNode)).dynamicCode();
    var report = new global.EcsReport(engine, {
        ruleId: 'SEC-002',
        title: 'Dynamic code execution',
        recommendation: 'Do not build code from strings. Use JSON.parse() for data, pass functions (not strings) ' +
            'to setTimeout/setInterval, and call the intended function directly. To run a script stored in a ' +
            'field, use GlideScopedEvaluator.evaluateScript().'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
